function reportOK(s,r){const sv=find(s,'services',r.serviceId),mt=find(s,'methods',sv.methodId);serviceOK(s,sv);recordsOK(s,sv);for(const k of ['receiptDate','activityStart','activityEnd','labLocation','itemDescription','itemCondition','deviations'])if(!r[k])fail('Informe incompleto: '+k);if(r.activityEnd<r.activityStart||r.activityStart<r.receiptDate)fail('Fechas de informe inconsistentes');if(mt.activity==='Calibración'&&!r.traceability)fail('Documenta trazabilidad metrológica');if(r.adjusted&&!r.beforeAfter)fail('Resultados antes/después del ajuste requeridos');if(r.intervalRequested&&!r.intervalAgreement)fail('No recomiendes intervalos sin acuerdo del cliente');if(r.conformity&&(!r.specification||!r.decisionRule||!r.conformityResult))fail('Conformidad exige especificación, regla acordada y resultados aplicables');if(r.conformity){const o=find(s,'orders',r.orderId);const q=o.quoteId?s.quotes.find(x=>x.id===o.quoteId):null;const c=o.contractId?s.contracts.find(x=>x.id===o.contractId):null;if(!q?.decisionRule&&!c?.decisionRule)fail('Registra el acuerdo de regla de decisión en cotización/contrato');}if(r.opinions){if(!r.opinionsBasis||!r.opinionsUserId)fail('Opiniones requieren base y responsable');if(!authorized(s,r.opinionsUserId,sv.methodId,'Opiniones'))fail('Responsable sin autorización específica para opiniones');}if((r.customerDataAffects||sv.receiptDeviation)&&!r.customerDisclaimer&&!sv.disclaimer)fail('Incluye limitación de responsabilidad por datos/condición del cliente');if(r.supersedes&&!r.amendmentReason)fail('Indica cambios y referencia al original');}
function approvalInbox(s,u){const list=[];for(const m of Object.keys(META))for(const r of s[m]){if((qualityUser(u)&&['Pendiente de Calidad','Pendiente de evaluación'].includes(r.status))||(tech(u)&&r.status==='Revisión técnica'&&['methods','services','reports','calibrations'].includes(m))||(qualityUser(u)&&m==='quotes'&&r.status==='Revisión'))list.push({module:m,id:r.id,title:r.folio+' · '+r.status,text:META[m].title+' · requiere revisión / autorización',approval:true});}return list;}
