function validSlot(r){const [a,b]=slot(r);if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)fail('El término debe ser posterior al inicio');if(b-a>31*86400000)fail('Programa como máximo 31 días por servicio/bloqueo');}
