 ['taxObligations30','Obligaciones fiscales','Contabilidad','OBF',[field28('name','Obligación / declaración','text',1),field28('period','Periodo AAAA-MM','text',1),field28('due','Fecha límite verificada','date',1),field28('ownerId','Responsable','ref:users',1),field28('basis','Fundamento / régimen aplicable','textarea',1),field28('amount','Importe validado MXN','number'),field28('receipt','Número de operación / acuse','text'),field28('evidence','Resultado y evidencia de presentación','textarea')]]
