function resultGroup30(a){if(a.resultGroup30)return a.resultGroup30;const c=String(a.satCode||'');if(a.type==='Ingreso')return c.startsWith('702')?'Ingresos financieros':c.startsWith('403')?'Otros ingresos':'Ingresos operativos';if(a.type!=='Gasto')return 'No aplica';if(c.startsWith('5'))return 'Costo de servicios';if(c.startsWith('613')||c.startsWith('614')||a.systemKey==='depExpense')return 'Depreciación y amortización';if(c.startsWith('701'))return 'Gastos financieros';if(c.startsWith('704')||c.startsWith('705'))return 'ISR y PTU';if(c.startsWith('703'))return 'Otros gastos';return 'Gastos operativos';}
function monthlyResults30(s,period){const start=period+'-01',end=new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5)),0)).toISOString().slice(0,10),cutoff=end<(s.today||today())?end:(s.today||today());const rows=(s.accounting||[]).filter(x=>x.status==='Contabilizada'&&x.due>=start&&x.due<=cutoff),totals=Object.fromEntries(RESULT_GROUPS30.map(x=>[x,0]));for(const a of s.accounts||[]){if(!['Ingreso','Gasto'].includes(a.type))continue;const balance=rows.reduce((n,x)=>n+(x.debitId===a.id?Number(x.amount):0)-(x.creditId===a.id?Number(x.amount):0),0),value=a.type==='Ingreso'?-balance:balance;totals[resultGroup30(a)]=(totals[resultGroup30(a)]||0)+value;}for(const k in totals)totals[k]=Math.round(totals[k]*100)/100;const round=n=>Math.round(n*100)/100,revenue=totals['Ingresos operativos'],gross=round(revenue-totals['Costo de servicios']),ebitda=round(gross-totals['Gastos operativos']),operating=round(ebitda-totals['Depreciación y amortización']),beforeTax=round(operating+totals['Ingresos financieros']-totals['Gastos financieros']+totals['Otros ingresos']-totals['Otros gastos']),net=round(beforeTax-totals['ISR y PTU']);return{period,start,end,cutoff,totals,revenue,gross,ebitda,operating,beforeTax,net,margin:revenue?round(ebitda/revenue*100):null,entries:rows.length,unclassified:(s.accounts||[]).filter(a=>['Ingreso','Gasto'].includes(a.type)&&resultGroup30(a)==='No aplica').length};}
const kpiBefore30=kpiValue;kpiValue=function(s,k,start,end,currentMonth){if(['EBITDA','Margen EBITDA'].includes(k.source)){const f=monthlyResults30({...s,today:s.today||end},start.slice(0,7));const value=k.source==='Margen EBITDA'?f.margin:f.ebitda;return{value:f.entries?value:null,n:f.ebitda,d:f.revenue,snapshot:false,reason:!f.entries?'Sin pólizas contabilizadas':value==null?'Sin ingresos operativos':''};}return kpiBefore30(s,k,start,end,currentMonth);};
for(const key of ['source','unit','category']){const f=META.kpis.fields.find(f=>f[0]===key);f[2]+=(key==='source'?'|EBITDA|Margen EBITDA':key==='unit'?'|MXN':'|Contabilidad');}

