// All generated outputs use one institutional engine; issued originals remain immutable.
reportPDF=async function(s,r,env){return institutionalPDF(s,'reports',r,env);};
quotePDF=async function(s,r,env){return(await institutionalPDF(s,'quotes',r,env,null,false)).bytes;};
recordPreviewPDF=async function(s,m,r,env,unsaved,attachment){if(!unsaved&&m==='reports'&&r.pdfKey){const o=await env.BUCKET.get(r.pdfKey);if(!o)fail('PDF no disponible',404);return new Uint8Array(await o.arrayBuffer());}return(await institutionalPDF(s,m,r,env,attachment,!!unsaved)).bytes;};

