 for(const p of s.policies){if(p.definitions?.startsWith('Registro: evidencia de actividad. Autorización:'))p.definitions=p.definitions.replace(/\. (?=[A-ZÁÉÍÓÚ][^:]+:)/g,'.\n');if(p.responsibilities?.startsWith('Dirección: aprobar recursos y responsabilidades. Calidad:'))p.responsibilities=p.responsibilities.replace(/\. (?=[A-ZÁÉÍÓÚ][^:]+:)/g,'.\n');}
