const cleanV8=cleanData;cleanData=function(m,data){const r=cleanV8(m,data);if(m==='policies'){r.developmentTables=cleanDevelopmentTables(data.developmentTables||[]);for(const k of ['definitions','responsibilities'])r[k]=r[k].split(/\r?\n/).map(x=>x.trim()).filter(Boolean).join('\n');}return r;};
function cleanDevelopmentTables(tables){if(!Array.isArray(tables)||tables.length>5)fail('Máximo 5 tablas de desarrollo');return tables.map(t=>{if(!Array.isArray(t.headers)||!t.headers.length||t.headers.length>8||!Array.isArray(t.rows)||t.rows.length>50)fail('Cada tabla admite 1–8 columnas y hasta 50 filas');const text=x=>{if(typeof x!=='string'||x.length>2000)fail('Texto de tabla inválido o mayor a 2000 caracteres');return x.trim();};return{title:text(t.title||''),headers:t.headers.map(text),rows:t.rows.map(row=>{if(!Array.isArray(row)||row.length!==t.headers.length)fail('Cada fila debe tener todas las columnas');return row.map(text);})};});}
const validateV8=validate;validate=function(s,m,r,old,u){validateV8(s,m,r,old,u);if(m==='surveys'){if(old?.status==='Respondida')fail('Una encuesta respondida no puede alterarse');if(r.expires<today())fail('Selecciona una vigencia futura');if(r.orderId&&find(s,'orders',r.orderId).clientId!==r.clientId)fail('La orden debe pertenecer al cliente');if(!old){r.token=crypto.randomUUID()+crypto.randomUUID();r.status='Abierta';}else{r.token=old.token;r.status=old.status;}}if(m==='surveyResponses')fail('Las respuestas se reciben exclusivamente desde el enlace público',403);};
function rowAccessible(s,u,m,r){if(!see(u,m))return false;if(m==='purchases'&&!canApprove(u,m)&&!['Administrador','Contabilidad','Auditor'].includes(u.role))return r.requesterId===u.id;if(u.role==='Técnico'){if(m==='services')return r.technicianId===u.id;if(['records','reports','environment'].includes(m))return s.services.find(x=>x.id===Number(r.serviceId))?.technicianId===u.id;if(m==='competence')return r.userId===u.id;}return true;}
const visibleV8=visibleState;visibleState=function(s,u){const out=visibleV8(s,u);for(const m of Object.keys(META))out[m]=out[m].filter(r=>rowAccessible(s,u,m,r));out.files=out.files.filter(f=>rowAccessible(s,u,f.module,s[f.module].find(r=>r.id===f.recordId)||{}));out.approvals=out.approvals.filter(x=>rowAccessible(s,u,x.module,s[x.module].find(r=>r.id===x.id)||{}));out.audit=out.audit.filter(x=>see(u,x.module)&&(!x.recordId||rowAccessible(s,u,x.module,s[x.module]?.find(r=>r.id===x.recordId)||{})));if(!see(u,'kpis'))out.kpiDashboard=[];out.wordTemplates=see(u,'labSettings')?out.wordTemplates:[];out.labProfile=see(u,'labSettings')?s.labSettings[0]:{name:s.labSettings[0].name,color:s.labSettings[0].color,logo:s.labSettings[0].logo};return out;};
async function publicSurveyRoute(req,url,s,env,etag){if(!url.pathname.startsWith('/api/survey/'))return null;const token=url.pathname.slice('/api/survey/'.length),invite=s.surveys.find(x=>x.token===token);if(!invite)fail('Enlace de encuesta no disponible',404);if(invite.status==='Respondida')fail('Esta encuesta ya fue respondida. Gracias por tu participación.',409);if(invite.status!=='Abierta'||invite.expires<today())fail('El enlace de encuesta ha vencido o está cerrado',410);if(req.method==='GET')return json({laboratory:{name:s.labSettings[0].name,color:s.labSettings[0].color,logo:s.labSettings[0].logo},questions:SURVEY_QUESTIONS,expires:invite.expires});if(req.method!=='POST')fail('Método no permitido',405);const raw=await req.text();if(raw.length>12000)fail('Respuesta demasiado grande',413);const b=JSON.parse(raw);if(b.website||!Array.isArray(b.scores)||b.scores.length!==5||b.scores.some(x=>!Number.isInteger(x)||x<1||x>5))fail('Responde las cinco preguntas con una puntuación de 1 a 5');if(typeof b.comment!=='string'||b.comment.length>2000)fail('Comentario máximo 2000 caracteres');const external={id:0,name:'Cliente externo'},row={id:Math.max(0,...s.surveyResponses.map(x=>x.id))+1,folio:folio(s,'surveyResponses'),name:'Respuesta de satisfacción',responseDate:today(),surveyId:invite.id,clientId:invite.clientId,orderId:invite.orderId,scores:b.scores,comment:b.comment.trim(),average:b.scores.reduce((a,b)=>a+b,0)/5,satisfaction:b.scores.reduce((a,b)=>a+b,0)/25*100,status:'Recibida',version:1,createdAt:now(),updatedAt:now(),createdBy:0};s.surveyResponses.push(row);invite.status='Respondida';invite.respondedAt=now();invite.updatedAt=now();audit(s,external,'surveyResponses',row.id,'Encuesta recibida',null,row);await save(env,s,etag);return json({ok:true,message:'Gracias. Tu respuesta quedó registrada.'});}
const SURVEY_HTML=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Encuesta de satisfacción</title><style>body{font-family:system-ui;background:#f3f6fb;color:#17263c;margin:0;padding:24px}main{max-width:700px;margin:auto;background:white;padding:32px;border-radius:18px;box-shadow:0 8px 40px #21365412}h1{font-size:26px}fieldset{border:1px solid #dce4ee;border-radius:10px;margin:20px 0;padding:16px}label{display:inline-flex;gap:6px;margin:8px}textarea{width:95%;min-height:100px;border:1px solid #c6d2e2;border-radius:8px;padding:10px}button{background:var(--color,#245fb8);color:white;border:0;padding:14px 24px;border-radius:8px;cursor:pointer}#trap{display:none}.error{color:#a12222}</style><main><div id="brand"></div><h1>Encuesta de satisfacción del cliente</h1><p>Evalúa el servicio recibido. No necesitas crear una cuenta. Escala: 1 = muy insatisfecho, 5 = muy satisfecho.</p><div id="message" role="status"></div><form id="survey" hidden><div id="questions"></div><label>Comentarios (opcional)</label><textarea name="comment" maxlength="2000"></textarea><div id="trap" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><p>Tu respuesta se vincula al servicio evaluado y se utiliza para mejorar la calidad. Evita incluir datos personales sensibles.</p><button>Enviar respuesta</button></form></main><script>const token=location.pathname.split('/').pop(),endpoint='/api/survey/'+encodeURIComponent(token),msg=document.getElementById('message'),form=document.getElementById('survey');async function init(){try{const r=await fetch(endpoint),d=await r.json();if(!r.ok)throw Error(d.error);document.getElementById('brand').textContent=d.laboratory.name;document.documentElement.style.setProperty('--color',d.laboratory.color);if(d.laboratory.logo){const im=document.createElement('img');im.src='data:'+d.laboratory.logo.mime+';base64,'+d.laboratory.logo.base64;im.style='max-width:100px;max-height:70px';document.getElementById('brand').prepend(im);}d.questions.forEach((q,i)=>{const field=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=(i+1)+'. '+q;field.append(legend);for(let n=1;n<=5;n++){const l=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name='q'+i;input.value=n;input.required=true;l.append(input,document.createTextNode(n));field.append(l);}document.getElementById('questions').append(field);});form.hidden=false;}catch(e){msg.textContent=e.message;}}form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{const f=new FormData(form),r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scores:[0,1,2,3,4].map(i=>Number(f.get('q'+i))),comment:f.get('comment'),website:f.get('website')})}),d=await r.json();if(!r.ok)throw Error(d.error);form.hidden=true;msg.textContent=d.message;}catch(e){msg.textContent=e.message;btn.disabled=false;}};init();</script></html>`;

