 const additions={Administrador:V10_MODULES,Calidad:['costCenters','travelRequests'], 'Responsable técnico':['costCenters','travelRequests','fuel','assets','suppliers'],Signatario:['costCenters','travelRequests'],Comercial:['crm','costCenters','travelRequests'],Técnico:['costCenters','travelRequests','fuel','assets','suppliers'],'Recursos humanos':['costCenters','travelRequests','travelAdmin'],Contabilidad:V10_MODULES.filter(x=>x!=='crm'),Auditor:['costCenters','travelRequests']};
 for(const role of s.roles){if(!additions[role.name])continue;const def=defaultsV9(role.name),eq=(a,b)=>a.length===b.length&&a.every(x=>b.includes(x));const uncustom=['view','edit','approve'].every(k=>eq(role.permissions[k].filter(x=>!V10_MODULES.includes(x)),def[k].filter(x=>!V10_MODULES.includes(x))));if(uncustom){role.permissions=def;role.permissions.view=role.permissions.view.filter(x=>!V10_MODULES.includes(x));role.permissions.edit=role.permissions.edit.filter(x=>!V10_MODULES.includes(x));role.permissions.approve=role.permissions.approve.filter(x=>!V10_MODULES.includes(x));const extra=additions[role.name];role.permissions.view.push(...extra);role.permissions.edit.push(...extra.filter(x=>!['payables','receivables','costCenters'].includes(x)&&!(role.name==='Auditor')&&!(role.name==='Calidad'&&x!=='travelRequests')&&!( ['Responsable técnico','Técnico'].includes(role.name)&&['assets','suppliers'].includes(x))));if(role.name==='Administrador'){role.permissions.edit.push('costCenters');role.permissions.approve.push(...ADMIN_FLOWS);}if(role.name==='Contabilidad')role.permissions.edit=role.permissions.edit.filter(x=>!['assets','purchaseOrders','purchaseBids','fuel','travelRequests'].includes(x)||x==='travelRequests');for(const k of ['view','edit','approve'])role.permissions[k]=[...new Set(role.permissions[k])];}role.defaultsVersion=10;}
 if(!s.roles.some(x=>x.name==='Compras'))newRecord(s,'roles',{name:'Compras',description:'Solicitudes, cotizaciones de proveedores, ejecución y recepción. Autoriza Administrador.',permissions:{view:['purchases','purchaseBids','purchaseOrders','suppliers','supplierEvaluations','inventory','movements','assets','costCenters','travelRequests','documents','manuals','clients'],edit:['purchases','purchaseBids','purchaseOrders','suppliers','supplierEvaluations','inventory','movements','travelRequests'],approve:[]}},system);
