function generic10(s,m,r,old){for(const[k,label,t,req]of META[m].fields){const v=r[k];if(req&&(v==null||v===''))fail('Completa: '+label);if(v===''||v==null)continue;if(t==='number'&&!Number.isFinite(v))fail('Número inválido: '+label);if(t.startsWith('ref:'))find(s,t.slice(4),v);if(t.startsWith('select:')&&!t.slice(7).split('|').includes(v))fail('Opción inválida: '+label);if(t==='date'&&!validDate37(v))fail('Fecha inválida: '+label);if(typeof v==='string'&&v.length>15000)fail('Texto demasiado largo');}if(old&&['Pendiente de Administrador','Autorizado','Autorizada','Recibida','Atendida','Comprobado','Cerrado','Rechazada','Cancelada'].includes(old.status))fail('Registro protegido; devolver a borrador antes de modificar');}
